-- Both tables have 999 records. Let me check if each supply has exactly one transportation record
SELECT COUNT(DISTINCT s.supplyregistry) FROM supplies s 
JOIN transportation t ON s.supplyregistry = t.transportsupref;

-- And check if there are any supplies without transportation records
SELECT COUNT(*) FROM supplies s 
WHERE NOT EXISTS (SELECT 1 FROM transportation t WHERE s.supplyregistry = t.transportsupref);
